package com.example.invoicing;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/**
 * A small plain-text report: totals per customer and currency.
 *
 * <p>Amounts in different currencies are never added together; each customer gets one line
 * per currency. The table is meant for a terminal, so long customer names are shortened with
 * {@link CustomerNames#displayName(String, int)}.
 */
public final class Report {

    static final int NAME_WIDTH = 24;

    private Report() {
    }

    /** One report line: a customer's totals in one currency. */
    public record Entry(String customerName, String currency, int invoices, BigDecimal net, BigDecimal gross) {

        Entry add(Invoice invoice) {
            return new Entry(customerName, currency, invoices + 1, net.add(invoice.net()), gross.add(invoice.gross()));
        }
    }

    /**
     * Aggregates invoices into one entry per (customer, currency). Customers are grouped by
     * their normalised name, so "Müller GmbH" written with a decomposed umlaut lands on the
     * same line. If {@code currency} is not null, other currencies are left out.
     */
    public static List<Entry> summarise(List<Invoice> invoices, String currency) {
        String wanted = currency == null ? null : currency.strip().toUpperCase(Locale.ROOT);
        Map<List<String>, Entry> totals = new LinkedHashMap<>();
        for (Invoice invoice : invoices) {
            if (wanted != null && !invoice.currency().equals(wanted)) {
                continue;
            }
            String customer = CustomerNames.normalise(invoice.customer());
            List<String> key = List.of(customer, invoice.currency());
            Entry entry = totals.getOrDefault(key,
                    new Entry(customer, invoice.currency(), 0, BigDecimal.ZERO, BigDecimal.ZERO));
            totals.put(key, entry.add(invoice));
        }
        List<Entry> entries = new ArrayList<>(totals.values());
        entries.sort(Comparator.comparing(Entry::customerName).thenComparing(Entry::currency));
        return entries;
    }

    /** All currencies. */
    public static List<Entry> summarise(List<Invoice> invoices) {
        return summarise(invoices, null);
    }

    /** Gross total per currency across all customers, ordered by currency code. */
    public static Map<String, BigDecimal> grandTotals(List<Entry> entries) {
        Map<String, BigDecimal> result = new TreeMap<>();
        for (Entry entry : entries) {
            result.merge(entry.currency(), entry.gross(), BigDecimal::add);
        }
        return result;
    }

    /** Fixed-width text table with a totals footer. */
    public static String render(List<Entry> entries) {
        String header = String.format(Locale.ROOT, "%-" + NAME_WIDTH + "s  %3s  %16s  %16s",
                "Customer", "#", "Net", "Gross");
        String rule = "-".repeat(header.length());
        StringBuilder out = new StringBuilder().append(header).append('\n').append(rule).append('\n');
        for (Entry entry : entries) {
            out.append(String.format(Locale.ROOT, "%s  %3d  %16s  %16s\n",
                    pad(CustomerNames.displayName(entry.customerName(), NAME_WIDTH)), entry.invoices(),
                    Money.format(entry.net(), entry.currency()), Money.format(entry.gross(), entry.currency())));
        }
        out.append(rule).append('\n');
        grandTotals(entries).forEach((code, amount) -> out.append(String.format(Locale.ROOT,
                "%-" + NAME_WIDTH + "s  %3s  %16s  %16s\n", "Total " + code, "", "", Money.format(amount, code))));
        return out.toString();
    }

    /** Summarise and render in one call; what the CLI prints. */
    public static String build(List<Invoice> invoices, String currency) {
        return render(summarise(invoices, currency));
    }

    /** Pads to the name column, counting user-perceived characters rather than chars. */
    private static String pad(String name) {
        int length = name.codePointCount(0, name.length());
        return name + " ".repeat(Math.max(0, NAME_WIDTH - length));
    }
}

package com.example.invoicing;

import java.text.BreakIterator;
import java.text.Collator;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Customer names, which are Unicode and arrive in every shape.
 *
 * <p>Names come from spreadsheets, web forms and old exports, so the same customer can appear
 * as {@code "Müller GmbH"}, {@code "Müller GmbH"} (a decomposed umlaut) or
 * {@code "  müller   gmbh "}. These helpers make them comparable without changing how they
 * are displayed.
 */
public final class CustomerNames {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    private CustomerNames() {
    }

    /** Canonical display form: NFC, single spaces, no outer whitespace. Case and accents stay. */
    public static String normalise(String name) {
        if (name == null) {
            throw new IllegalArgumentException("customer name is missing");
        }
        String composed = Normalizer.normalize(name, Normalizer.Form.NFC);
        return WHITESPACE.matcher(composed.strip()).replaceAll(" ");
    }

    /** Removes combining marks: {@code "Čapek"} becomes {@code "Capek"}. */
    public static String stripAccents(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("");
    }

    /**
     * Human-friendly order: accent- and case-insensitive first (a root-locale {@link Collator}
     * at primary strength), then the normalised name itself, so the order is total and
     * deterministic ({@code "Capek"} before {@code "Čapek"}).
     */
    public static Comparator<String> comparator() {
        Collator collator = Collator.getInstance(Locale.ROOT);
        collator.setStrength(Collator.PRIMARY);
        collator.setDecomposition(Collator.CANONICAL_DECOMPOSITION);
        Comparator<String> primary = (a, b) -> collator.compare(normalise(a), normalise(b));
        return primary.thenComparing(CustomerNames::normalise);
    }

    /** True if {@code query} occurs in {@code name}, ignoring case and accents. */
    public static boolean matches(String name, String query) {
        String haystack = stripAccents(normalise(name)).toLowerCase(Locale.ROOT);
        String needle = stripAccents(normalise(query)).toLowerCase(Locale.ROOT);
        return haystack.contains(needle);
    }

    /** Initials of the first two words, keeping accents: {@code "Élodie Durand"} gives {@code "ÉD"}. */
    public static String initials(String name) {
        StringBuilder out = new StringBuilder();
        for (String word : normalise(name).split(" ")) {
            if (out.length() >= 2) {
                break;
            }
            if (!word.isEmpty() && Character.isLetter(word.codePointAt(0))) {
                out.appendCodePoint(Character.toUpperCase(word.codePointAt(0)));
            }
        }
        return out.toString();
    }

    /**
     * Fits {@code name} into {@code width} user-perceived characters, ending with an ellipsis
     * when cut. Never splits a letter from its combining accent, and replaces the newlines
     * some exports contain with spaces.
     */
    public static String displayName(String name, int width) {
        if (width < 1) {
            throw new IllegalArgumentException("width must be positive");
        }
        String clean = normalise(name.replace('\r', ' ').replace('\n', ' '));
        List<String> clusters = graphemes(clean);
        if (clusters.size() <= width) {
            return clean;
        }
        return String.join("", clusters.subList(0, width - 1)) + "…";
    }

    private static List<String> graphemes(String text) {
        BreakIterator iterator = BreakIterator.getCharacterInstance(Locale.ROOT);
        iterator.setText(text);
        List<String> clusters = new ArrayList<>();
        int start = iterator.first();
        for (int end = iterator.next(); end != BreakIterator.DONE; start = end, end = iterator.next()) {
            clusters.add(text.substring(start, end));
        }
        return clusters;
    }
}

package com.example.invoicing;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class ReportTest {

    private static final List<Invoice> FIXTURE = FixtureLoader.load(Path.of("data/invoices.csv"));

    @Test
    void groupsByNormalisedCustomerAndCurrency() {
        List<Invoice> invoices = List.of(
                Invoice.of("1", "Müller GmbH", "10", "0", "EUR"),
                Invoice.of("2", "Müller  GmbH", "5", "0", "EUR"),
                Invoice.of("3", "Müller GmbH", "7", "0", "USD"));
        List<Report.Entry> entries = Report.summarise(invoices);
        assertEquals(2, entries.size());
        assertEquals(2, entries.get(0).invoices());
        assertEquals(new BigDecimal("15"), entries.get(0).net());
        assertEquals("Müller GmbH", entries.get(0).customerName());
    }

    @Test
    void ordersPlainNamesAlphabeticallyThenByCurrency() {
        List<Invoice> invoices = List.of(
                Invoice.of("1", "Beta", "1", "0", "USD"),
                Invoice.of("2", "Alpha", "1", "0", "EUR"),
                Invoice.of("3", "Beta", "1", "0", "EUR"));
        assertEquals(List.of("Alpha/EUR", "Beta/EUR", "Beta/USD"), Report.summarise(invoices).stream()
                .map(e -> e.customerName() + "/" + e.currency()).toList());
    }

    @Test
    void currencyFilterKeepsOnlyThatCurrency() {
        List<Report.Entry> entries = Report.summarise(FIXTURE, "czk");
        assertEquals(2, entries.size());
        assertTrue(entries.stream().allMatch(e -> e.currency().equals("CZK")));
    }

    @Test
    void grandTotalsNeverMixCurrencies() {
        Map<String, BigDecimal> totals = Report.grandTotals(Report.summarise(FIXTURE));
        assertEquals(List.of("CZK", "EUR", "GBP", "USD"), List.copyOf(totals.keySet()));
        assertEquals(new BigDecimal("73205.00"), totals.get("CZK"));
    }

    @Test
    void rendersATableWithTotals() {
        String table = Report.build(FIXTURE, "GBP");
        assertTrue(table.startsWith("Customer"), table);
        assertTrue(table.contains("Zeta Analytics"), table);
        assertTrue(table.contains("1,176.48 GBP"), table);
        assertTrue(table.contains("Total GBP"), table);
        assertFalse(table.contains("EUR"), table);
    }

    @Test
    void shortensLongNamesInTheTable() {
        String table = Report.build(List.of(Invoice.of("1", "A very long customer name indeed, Ltd", "1", "0", "EUR")), null);
        assertTrue(table.contains("A very long customer na…"), table);
    }
}
